entries[210412] = { ["name"] = "Flourishing Whimsydrake", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"These playful protectors of the Emerald Dream may be larger than their faerie dragon relatives, but they are no less mischievous.\"\nQuest:\nEmerald Welcome\nZone:\nEmerald Dream" }
