entries[210575] = { ["name"] = "Hatuun's Memory Stone", ["text"] = "Quest Item\n\"Early morning in the Conservatory. Birdsong.\"" }
entries[210576] = { ["name"] = "Romuul's Memory Stone", ["text"] = "Quest Item\n\"The defense crystal had one broken condenser. Just one.\"" }
entries[210577] = { ["name"] = "Ataanya's Memory Stone", ["text"] = "Quest Item\n\"Ink stains on his tendrils where they touched his schematics.\"" }
entries[210578] = { ["name"] = "Arzaal's Memory Stone", ["text"] = "Quest Item\n\"I stepped away from their blood when it touched my hooves.\"" }
entries[210579] = { ["name"] = "Boros's Memory Stone", ["text"] = "Quest Item\n\"It was easier to flee a planet than defend it. I agreed. Again and again.\"" }
entries[210580] = { ["name"] = "Nobundo's Memory Stone", ["text"] = "Quest Item\n\"In that moment, I was empty. I wished to live. I hoped to die.\"" }
entries[210581] = { ["name"] = "Ishanah's Memory Stone", ["text"] = "Quest Item\n\"I saw his face when I awoke. There were tears in his eyes. Then the light went out of them.\"" }
entries[210582] = { ["name"] = "Jadaar's Memory Stone", ["text"] = "Quest Item\n\"Clearing away the broken walls. There were children.\"" }
entries[210583] = { ["name"] = "Kuros's Memory Stone", ["text"] = "Quest Item" }
entries[210584] = { ["name"] = "Naielle's Memory Stone", ["text"] = "Quest Item\n\"They had catapults. We should have seen their tracks outside the walls.\"" }
entries[210585] = { ["name"] = "Aesom's Memory Stone", ["text"] = "Quest Item" }
entries[210586] = { ["name"] = "Akama's Memory Stone", ["text"] = "Quest Item\n\"I was something, not someone. Trading chains, again and again.\"" }
entries[210587] = { ["name"] = "Nemuraan's Memory Stone", ["text"] = "Quest Item" }
entries[210588] = { ["name"] = "Oman's Memory Stone", ["text"] = "Quest Item\n\"The passing of Hespera, lost to the wreck of the Genedar.\"" }
entries[210591] = { ["name"] = "Tishamaat Memory Stones", ["text"] = "Quest Item\n\"A smooth, palm-sized stone inscribed with a painful memory. It is deceptively heavy.\"" }
entries[210592] = { ["name"] = "Altar Fragment", ["text"] = "Quest Item\n\"Fragment of Lukou's regeneration altar.\"" }
entries[210593] = { ["name"] = "Lukou's Altar Centerpiece", ["text"] = "Quest Item\n\"The biggest fragment of Lukou's regeneration altar.\"" }
