entries[210769] = { ["name"] = "Reins of the Springtide Dreamtalon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 18 with the Dream Wardens.\nSell Price:\n\"Surging with the kind of energy and enthusiasm that can make anyone envious.\"\nVendor:\nTalisa Whisperbloom\nZone:\nEmerald Dream\nCost:\n1" }
entries[210770] = { ["name"] = "Satchel of Drake's Dreaming Crests", ["text"] = "Binds when picked up\nUse: Collect 15 Drake's Dreaming Crests. These crests ignore the seasonal cap.\nComplete the quest \"Dreaming of Crests\" from Vaskarn in Central Encampment to be able to downgrade your Dreaming Crests." }
entries[210774] = { ["name"] = "Reins of the Ochre Dreamtalon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Playful dreamtalons often decorate themselves in a myriad of colors that only autumn offers.\"\nQuest:\nA Little Hope is Never Without Worth\nZone:\nEmerald Dream" }
entries[210775] = { ["name"] = "Reins of the Snowfluff Dreamtalon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 18 with the Dream Wardens.\nSell Price:\n\"As lighthearted and gentle as the snow, they can bounce from one snowdrift to the next without leaving a print.\"\nVendor:\nTalisa Whisperbloom\nZone:\nEmerald Dream\nCost:\n1" }
entries[210776] = { ["name"] = "Lesser Dream Infusion", ["text"] = "Binds to Warband\n\"A glowing green gem which contains a small amount of dream energy.\"" }
entries[210777] = { ["name"] = "Drowsey", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)\nYou must have a Rock Snail pet in your collection to be able to infuse a new one with dream energy." }
entries[210778] = { ["name"] = "Archivist's Wind Totem", ["text"] = "Quest Item\nUnique\nUse: Summons a wind totem to your location, to help with excavation. (5 Sec Cooldown)" }
entries[210780] = { ["name"] = "Lesser Ember of Fyr'alath", ["text"] = "Binds when picked up\nUse: Embrace the ember, permanently increasing your chances of acquiring Fyr'alath the Dreamrender.\n\"The Dreamrender's anthem calls to you from its core.\"" }
entries[210782] = { ["name"] = "Slumbering Moonfish", ["text"] = "Binds when picked up\nUse: Toss the Moonfish back into the waters of Amirdrassil, applying a stack of Moonfish Essence.\n\"This ghostly fish is found only in the waters of Amirdrassil. The fish is attracted to your attunement with the Emerald Dream.\"\nSell Price:" }
entries[210783] = { ["name"] = "Awakening Sunfish", ["text"] = "Binds when picked up\nUse: Toss the Sunfish back into the waters of Amirdrassil, applying a stack of Sunfish Essence.\n\"This playful fish can survive molten temperatures and is found only in Amirdrassil. It seems to be drawn to the inherit bond between you and the World Tree.\"\nSell Price:" }
entries[210784] = { ["name"] = "Xena, the Whimsical Whiskerfish", ["text"] = "Binds when picked up\nUse: Return Xena back to the waters of Amirdrassil.\n\"All forms of light reflect off Xena's prismatic scales with an incandescence that can only be described as whimsical.\"\nSell Price:" }
entries[210785] = { ["name"] = "Snorr", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)\nYou must have a Wyvern Whelp pet in your collection to be able to infuse a new one with dream energy." }
