entries[210813] = { ["name"] = "Wild Experimentation", ["text"] = "\"Experiment with volatile reagents in hopes of discovering new recipes.\"" }
entries[210814] = { ["name"] = "Artisan's Acuity", ["text"] = "Binds when picked up\nCrafting Reagent\n\"A mysterious reagent beyond mortal comprehension that is bestowed upon master crafters. It is often used in high-value crafts and recrafting, even if its effects are purely superstition.\"" }
entries[210815] = { ["name"] = "Coreway Catalyst", ["text"] = "Binds when picked up\nCrafting Reagent\n\"Acquired as a byproduct from reclaiming excess concoctions.\"\nSell Price:" }
entries[210816] = { ["name"] = "Algari Alchemist Stone", ["text"] = "Binds when picked up\nUnique-Equipped: Alchemist Stone (1)\nTrinket\n+ 924 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 5955 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\n\"Can be used for transmutations in place of a Philosopher's Stone.\"\nSell Price:" }
entries[210819] = { ["name"] = "Chocolate-Covered Cherries", ["text"] = "Use: Restores ( 175 * 30 / 5) health over 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 2 Stamina and Versatility for 15 min.\nSell Price:" }
entries[210821] = { ["name"] = "Berry Chocolate Tart", ["text"] = "Use: Restores ( 375 * 30 / 5) health over 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 2 Stamina and Versatility for 15 min.\nSell Price:" }
entries[210826] = { ["name"] = "Harvestbot Repair Kit", ["text"] = "Binds when picked up\nUnique\nUse: Learn the basics of using Radiant Remnants to repair Disabled Harvestbots.\n\nOnce repaired they will help battle enemies near them.\n\"Ezgi's instructions and tools to repair harvestbots.\"\nSell Price:" }
entries[210827] = { ["name"] = "Ezgi's Gizmo", ["text"] = "Binds when picked up\nUnique (10)\nUse: An emergency signal that activates available harvestbot to help clear Stillstone Pond and Torchlight Mine of threats.\nRequires Renown Rank 12 with the Hallowfall Arathi.\n\"Once you've learned to fixed one, the rest are easy!\"\nSell Price:" }
entries[210828] = { ["name"] = "Dilution Solution", ["text"] = "Binds when picked up\nCrafting Reagent\n\"An alchemical reagent used for neutralizing the effects of potions and flasks. Can be purchased from Alchemy suppliers throughout Khaz Algar.\"\nSell Price:" }
entries[210829] = { ["name"] = "Neutralize Concoctions", ["text"] = "\"Extract Coreway Catalysts from a large quantity of unwanted potions or flasks.\"" }
entries[210830] = { ["name"] = "Finished Rush'kah Mask", ["text"] = "Quest Item\nRequires level 50 to 80 ( 80)\n\"A newly created Darkspear rush'kah mask.\"" }
entries[210831] = { ["name"] = "Delugen", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nYou must have a Ottuk mount in your collection to be able to infuse a new one with dream energy.\n\n\"Imagine being so engrossed by a dream that it feels real; some might even call it a delusion.\"\nVendor:\nElianna\nZone:\nEmerald Dream\nCost:\n1" }
entries[210833] = { ["name"] = "Talont", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nYou must have a Dreamtalon mount in your collection to be able to infuse a new one with dream energy.\n\n\"Some daydreams are filled with wondrous possibilities, but shatter when reminded of reality's limitations. Some dreams are not so burdened, even when they carry a rider.\"\nVendor:\nElianna\nZone:\nEmerald Dream\nCost:\n1" }
