entries[210944] = { ["name"] = "Emerald Mark of Mastery", ["text"] = "Dragonflight Season 3\nBinds when picked up\nUnique\n\"Awarded for outstanding service to Dragonkind. Bring it to Theozhaklos the Curious at the Wellspring Overlook in the Emerald Dream to receive powerful equipment for your efforts.\"" }
entries[210945] = { ["name"] = "Stargrazer", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nYou must have a Dreamstag mount in your collection to be able to infuse a new one with dream energy.\n\n\"One can't help but think what it might feel like to pluck the stars from their fixture in the sky. Perhaps, Stargrazer will show us how someday.\"\nVendor:\nElianna\nZone:\nEmerald Dream\nCost:\n1" }
entries[210946] = { ["name"] = "Mammyth", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nYou must have a Magmammoth mount in your collection to be able to infuse a new one with dream energy.\n\n\"In the Dream, sometimes the myth is more real than its basis.\"\nVendor:\nElianna\nZone:\nEmerald Dream\nCost:\n1" }
entries[210947] = { ["name"] = "Flame-Warped Curio", ["text"] = "Binds when picked up\n\"A reminder of the fiery future Fyrakk sought. Kirasztia at the Wellspring Overlook in the Emerald Dream may know how to unlock the secrets that lay within.\"\nSell Price:" }
entries[210948] = { ["name"] = "Imagiwing", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nYou must have a Shalewing mount in your collection to be able to infuse a new one with dream energy.\n\n\"There's nothing more beautiful than watching your imagination take flight.\"\nVendor:\nElianna\nZone:\nEmerald Dream\nCost:\n1" }
entries[210950] = { ["name"] = "Insight of Q'onzu", ["text"] = "Binds when picked up\nUse: Grants the BEST amount of reputation with the Dream Wardens. (2 Sec Cooldown)\n\"Who needs material possessions when you've witnessed Q'onzu?\"" }
