entries[210961] = { ["name"] = "Alara'shinu", ["text"] = "Binds when picked up\nOne-Hand Warglaive\n686 - 1,086 Damage Speed 2.60\n(340.8 damage per second)\n+300 Agility\n+1,064 Stamina\n+ 194 Critical Strike\n+ 237 Mastery\nDurability 120 / 120\n\"Finding beauty in imperfection.\"\nSell Price:" }
