entries[210969] = { ["name"] = "Salatrancer", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nYou must have a Salamanther mount in your collection to be able to infuse a new one with dream energy.\n\n\"While most salamanthers' attention jumps freely from one attraction to the next, this one enjoys long periods of deep observation.\"\nVendor:\nElianna\nZone:\nEmerald Dream\nCost:\n1" }
entries[210970] = { ["name"] = "Crumbled Keepsake", ["text"] = "Fungal Folly\n\"An older keepsake meant to stay with the earthen whom it belonged to.\"" }
entries[210973] = { ["name"] = "Heartseeker Mana Ray", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses a Heartseeker Mana Ray. This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Someone once told this mana ray it was adorable. It has been pursuing that positive feeling ever since.\"\nWorld Event:\nLove is in the Air\nCost:\n270" }
entries[210974] = { ["name"] = "Eyes For You Only", ["text"] = "Binds when picked up\nToy\nUse: Tune out non-party members. (30 Min Cooldown)" }
entries[210975] = { ["name"] = "Date Simulation Modulator", ["text"] = "Binds when used\nToy\nUse: Place down a Date Simulation Modulator for up to 2 hrs that allows you to view the world from a different perspective.\n\nA cloaking device attached to this machine ensures that only members of your party or raid can see the machine and its effects.\n\nCan only be used outside. (2 Hrs Cooldown)\nSell Price:" }
